"""Upper-bound step-function constructions for Problem 4 (C'_4 and C_4).

Verifies improved step-function upper bounds for the third autocorrelation
inequality with signed functions on [-1/4, 1/4] (Section B.3 of arXiv:2511.02864):
  1. C'_4 (with |.| inside the max):
     - N = 150: C'_4 <= 1.4621879468 (improving 1.4687620697 at N = 150)
     - N = 600: C'_4 <= 1.4599890469
  2. C_4 (without |.| inside the max):
     - N = 800: C_4  <= 1.4554649475 (improving 1.4556427954)
"""

import numpy as np


def evaluate_SignedLInf(sequence: list[float]) -> tuple[float, float]:
  """Evaluates a sequence of coefficients (verbatim from mathematical_results.ipynb)."""
  if not isinstance(sequence, list):
    return np.inf, np.inf
  if not sequence:
    return np.inf, np.inf
  for x in sequence:
    if isinstance(x, bool) or not isinstance(x, (int, float)):
      return np.inf, np.inf
    if np.isnan(x) or np.isinf(x):
      return np.inf, np.inf
  sequence = [float(x) for x in sequence]
  sequence = [max(-1000.0, x) for x in sequence]
  sequence = [min(1000.0, x) for x in sequence]
  n = len(sequence)
  b_sequence = np.convolve(sequence, sequence)
  max_b1 = max(np.abs(b_sequence))
  max_b2 = np.abs(max(b_sequence))
  sum_a = np.sum(sequence)
  if sum_a < 0.01:
    return np.inf, np.inf
  return float(2 * n * max_b1 / (sum_a**2)), float(2 * n * max_b2 / (sum_a**2))


